INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 0, 'theory', 'Quiz: what an operating system is and where Unix came from');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 0, 0, 'What three jobs does an operating system do?', '["Hides the hardware behind simple abstractions, shares resources between programs and protects them from each other", "Draws the interface, stores documents and checks spelling", "Compiles programs, runs them and deletes them", "Speeds up the processor, cools the memory and saves battery"]', 0, 'Everything else follows from these: files and processes are abstractions, the scheduler and memory manager share resources, CPU modes provide protection.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 0, 1, 'Why can''t an ordinary program read a disk sector directly?', '["The program lacks the necessary libraries", "The disk is available only over the network", "It runs in the CPU''s user mode, and instructions that access devices are allowed only to the kernel in privileged mode", "Disk sectors are encrypted on every read"]', 2, 'This is a hardware restriction, not a convention: trying to execute a privileged instruction raises an exception.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 0, 2, 'How does an ordinary program get a service from the kernel?', '["By jumping to an address in kernel memory", "Through a system call, the one checked door from user mode into kernel mode", "By writing to a configuration file", "Through a special network port"]', 1, 'A system call switches the processor into kernel mode and passes control to a known handler, where permissions and arguments are checked.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 0, 3, 'Why could Unix be moved to different computers?', '["It was written entirely in the assembly language of a common processor", "It was only ever run in virtual machines", "It did not use memory", "It was rewritten in C, so a port only needed a small machine-dependent part reworked"]', 3, 'In 1973 Ritchie created C precisely for systems programming. That is what made Unix independent of any particular hardware.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 0, 4, 'What is Linux in the strict sense of the word?', '["A complete operating system with an interface and applications", "A name for all Unix systems", "Only the kernel; with GNU utilities, libraries and packages it forms a distribution", "A command shell for the BSD kernel"]', 2, 'That''s why Debian and Fedora are distributions, while their kernel comes from the same family: Linux.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 0, 5, 'How does a monolithic kernel differ from a microkernel?', '["A monolithic kernel''s subsystems run in one address space in privileged mode; a microkernel moves most of them out into ordinary processes", "A monolithic kernel does not support modules", "A microkernel is always faster than a monolithic one", "A monolithic kernel has no drivers"]', 0, 'Linux is monolithic but modular: drivers can be loaded, and they still run with kernel privileges.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 0, 6, 'What does the POSIX standard describe?', '["The ext4 file system format", "The protocol between the kernel and the network card", "The design of the x86 processor", "A common interface of Unix-like systems: system calls, utilities and shell behavior"]', 3, 'Thanks to POSIX, a program written for one system builds on another with small changes.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 0, 7, 'What does the principle "everything is a file" mean?', '["All programs are stored in a single directory", "Disks, terminals, pipes and much more are accessed through the same open, read and write calls", "Files can''t be deleted while they are open", "Every file must have an extension"]', 1, 'A uniform interface is the main reason small programs can be joined into pipelines.');
